      "description": "Signed change, e.g. +12.4%."
    },
    {
      "name": "trend",
      "type": "'up' | 'down' | 'flat'",
      "required": false,
      "defaultValue": "flat",
      "description": "Delta direction color + arrow glyph.",
      "enum": [
